import {draftMetaView,META_ROLES} from './draft-meta.js';
export function draftMetaMarkup(c,d,m){
 const {data,state:s,ui,E,esc,img,btn}=c;
 const view=draftMetaView(data,{date:s.date,competition:m.competition,phase:m.phase??s.phase?.key,patch:d.patch,mode:ui.draftMetaMode??'event'});if(!view)return '';
 const open=ui.draftMetaOpen!==false,role=ui.draftMetaRole??'all',human=E.draftTurn(d)?.team===s.myTeam&&!ui.draftBusy;
 const lanes=role==='all'?META_ROLES:[role],limit=role==='all'?4:12;
 const laneMarkup=r=>{
  const rows=view.roles[r].map(ch=>({...ch,unavailable:E.draftUnavailableReason(s,d,ch.id)})).filter(ch=>!ui.draftMetaAvailable||!ch.unavailable).slice(0,limit);
  return `<section class="meta-lane" data-meta-lane="${r}"><h3>${r}<small>${esc(E.ROLE_NAMES[r])}</small></h3><div class="meta-champions">${rows.length?rows.map(ch=>`<button class="meta-champion ${ch.priority==='OP'?'is-op':''} ${ch.unavailable?'is-unavailable':''}" data-action="draft-pick" data-id="${ch.id}" data-meta-champion="${ch.id}" ${!human||ch.unavailable?'disabled':''} title="${esc(ch.name+' · '+ch.observedRoles.join('/')+' · '+(ch.unavailable||'선택 후 확정'))}">${img(ch.id)}<span class="meta-champ-text"><strong>${esc(ch.name)} <b>${ch.priority}</b>${ch.flex?'<i>FLEX</i>':''}</strong><small>1세트 P/B ${ch.presence===null?'—':Math.round(ch.presence*100)+'%'} · ${ch.picks}픽${ch.wins===null?'':` ${ch.wins}승`}</small>${ch.unavailable?`<em>${esc(ch.unavailable)}</em>`:''}</span></button>`).join(''):'<p class="meta-empty">조건에 맞는 관측 픽이 없습니다.</p>'}</div></section>`;
 };
 return `<section class="draft-meta-panel" aria-label="대회별 포지션 메타"><header><div><span>2026 대회 메타</span><h2>${esc(view.label??m.competition)} <small>PATCH ${esc(E.patchLabel(d.patch))}</small></h2></div>${btn(open?'메타 접기':'OP·주요 픽 보기','draft-meta-toggle','aria-expanded="'+open+'"','compact ghost')}</header>${open?`<div class="meta-controls"><div class="meta-modes">${btn('대회·패치 기록','draft-meta-mode','data-id="event" aria-pressed="'+((ui.draftMetaMode??'event')==='event')+'"',(ui.draftMetaMode??'event')==='event'?'compact primary':'compact')}${btn('현재 시점 참고','draft-meta-mode','data-id="prior" aria-pressed="'+(ui.draftMetaMode==='prior')+'"',ui.draftMetaMode==='prior'?'compact primary':'compact')}</div><div class="meta-roles">${['all',...META_ROLES].map(r=>btn(r==='all'?'전 라인':r,'draft-meta-role',`data-id="${r}" aria-pressed="${role===r}"`,role===r?'compact active':'compact')).join('')}</div>${btn(ui.draftMetaAvailable?'선택 가능만 ✓':'선택 가능만','draft-meta-available',`aria-pressed="${!!ui.draftMetaAvailable}"`,'compact ghost')}</div><p class="meta-evidence">${view.empty?'해당 조건의 수집 기록이 없습니다.':view.mode==='event'?`해당 대회·패치 수집 기록 ${view.games}세트 · 1세트 ${view.openingGames}경기 · ${view.firstDate.slice(5,10)}~${view.lastDate.slice(5,10)}${view.partial?' · 일부 기록(10/18까지)':''} · 시즌 진행일 이후 기록도 포함한 참고표입니다.`:`${view.fallback?'해당 대회·패치 기록이 없어 ':''}게임 날짜 이전 최근 주요 대회 1세트 ${view.games}경기 참고 · ${view.lastDate?.slice(0,10)??'기록 없음'}까지`}</p><div class="meta-lanes ${role!=='all'?'single-lane':''}">${lanes.map(laneMarkup).join('')}</div><p class="meta-footnote">OP: 1세트 표본 10경기 이상·밴픽률 65% 이상인 관측 우선 픽입니다. 라인은 실제 출전 기록 기준이며 픽의 포지션을 고정하지 않습니다. 최종 배치는 밴픽 종료 후 정합니다.</p>`:''}</section>`;
}
